from __future__ import annotations

"""Turn token usage into the per-request dollar figures finance reconciles.

The meter feeds an internal spend dashboard. Each priced request is one row;
``summarize_costs`` rolls rows up into the totals shown next to the monthly
OpenAI invoice.
"""

from openai_usage_models import (
    ModelPrice,
    TokenUsage,
    build_price_book,
    extract_stream_usage,
)


def _per_million(tokens: int, rate_per_1m: float) -> float:
    return tokens / 1_000_000 * rate_per_1m


def price_request(usage: TokenUsage, price: ModelPrice) -> dict[str, object]:
    """Price a single request's usage against one model's rates."""

    input_cost = _per_million(usage.prompt_tokens, price.input_per_1m)
    cached_cost = _per_million(usage.cached_tokens, price.cached_input_per_1m)
    output_cost = _per_million(usage.completion_tokens, price.output_per_1m)

    return {
        "model": price.model,
        "prompt_tokens": usage.prompt_tokens,
        "cached_tokens": usage.cached_tokens,
        "completion_tokens": usage.completion_tokens,
        "input_cost": input_cost,
        "cached_cost": cached_cost,
        "output_cost": output_cost,
        "total_cost": input_cost + output_cost,
    }


def summarize_costs(rows: list[dict[str, object]]) -> dict[str, object]:
    return {
        "request_count": len(rows),
        "total_cost": sum(float(row["total_cost"]) for row in rows),
        "total_prompt_tokens": sum(int(row["prompt_tokens"]) for row in rows),
        "total_cached_tokens": sum(int(row["cached_tokens"]) for row in rows),
        "total_completion_tokens": sum(int(row["completion_tokens"]) for row in rows),
    }


class UsageMeter:
    """Accumulates priced rows for a billing window."""

    def __init__(self, price_book: dict[str, ModelPrice] | None = None) -> None:
        self._price_book = price_book if price_book is not None else build_price_book()
        self._rows: list[dict[str, object]] = []

    def _price_for(self, model: str) -> ModelPrice:
        price = self._price_book.get(model)
        if price is None:
            raise KeyError(f"no price configured for model {model!r}")
        return price

    def record_response(self, model: str, response: dict) -> dict[str, object]:
        usage = TokenUsage.from_response(response)
        row = price_request(usage, self._price_for(model))
        self._rows.append(row)
        return row

    def record_stream(self, model: str, chunks: list[dict]) -> dict[str, object]:
        usage = extract_stream_usage(chunks)
        row = price_request(usage, self._price_for(model))
        self._rows.append(row)
        return row

    def summarize(self) -> dict[str, object]:
        return summarize_costs(self._rows)

    @property
    def rows(self) -> list[dict[str, object]]:
        return list(self._rows)

