from __future__ import annotations

"""Pricing inputs and normalized token usage for OpenAI responses.

A Chat Completions response reports usage like::

    "usage": {
        "prompt_tokens": 1000,
        "completion_tokens": 200,
        "total_tokens": 1200,
        "prompt_tokens_details": {"cached_tokens": 800}
    }

``cached_tokens`` is the slice of ``prompt_tokens`` that hit the prompt cache.
It is a subset of the prompt total, not an extra line item, and it bills at a
lower input rate. Streamed responses only include this block in the final
chunk, and only when the request asked for it.
"""

from dataclasses import dataclass


class MissingUsageError(ValueError):
    """Raised when a response carries no usage block to price."""


@dataclass(frozen=True)
class ModelPrice:
    """Per-1M-token prices in USD for one model."""

    model: str
    input_per_1m: float
    cached_input_per_1m: float
    output_per_1m: float


@dataclass(frozen=True)
class TokenUsage:
    prompt_tokens: int
    completion_tokens: int
    total_tokens: int
    cached_tokens: int

    def __post_init__(self) -> None:
        for label, value in (
            ("prompt_tokens", self.prompt_tokens),
            ("completion_tokens", self.completion_tokens),
            ("cached_tokens", self.cached_tokens),
        ):
            if value < 0:
                raise ValueError(f"{label} must be non-negative")
        if self.cached_tokens > self.prompt_tokens:
            raise ValueError("cached_tokens cannot exceed prompt_tokens")

    @classmethod
    def from_response(cls, response: dict) -> "TokenUsage":
        usage = response.get("usage")
        if not usage:
            raise MissingUsageError(
                "response has no usage; streamed calls must set "
                "stream_options.include_usage"
            )
        details = usage.get("prompt_tokens_details") or {}
        prompt = int(usage["prompt_tokens"])
        completion = int(usage["completion_tokens"])
        total = int(usage.get("total_tokens", prompt + completion))
        cached = int(details.get("cached_tokens", 0))
        return cls(
            prompt_tokens=prompt,
            completion_tokens=completion,
            total_tokens=total,
            cached_tokens=cached,
        )


def extract_stream_usage(chunks: list[dict]) -> TokenUsage:
    """Pull usage from the final chunk of a streamed response.

    Streaming with ``stream_options.include_usage`` appends a trailing chunk
    that carries the usage block while its ``choices`` list is empty. If no
    chunk carries usage, the stream was not asked to report it.
    """

    for chunk in reversed(chunks):
        if chunk.get("usage"):
            return TokenUsage.from_response(chunk)
    raise MissingUsageError("no streamed chunk carried a usage block")


def build_price_book() -> dict[str, ModelPrice]:
    prices = (
        ModelPrice("gpt-4o", input_per_1m=2.50, cached_input_per_1m=1.25, output_per_1m=10.00),
        ModelPrice("gpt-4o-mini", input_per_1m=0.15, cached_input_per_1m=0.075, output_per_1m=0.60),
    )
    return {price.model: price for price in prices}

